const l=[],hid=[];ex.filter(e=>!e.hold&&(e.kind||'exam')==kind&&e.grade==U.grade&&e.end>=lnow()).forEach(e=>{if(!audOk(e))hid.push([e,audWhy(e)]);else if(e.grp&&norm(e.grp)!=norm(U.grp))hid.push([e,`مخصص لمجموعة «${e.grp}» ومجموعتك «${U.grp||'غير محددة'}»`]);else if((e.only||[]).length&&!e.only.includes(U.username))hid.push([e,'مخصص لطلاب محددين']);else l.push(e)});
