const gr=g.createLinearGradient(0,0,W,H);gr.addColorStop(0,'#4f46e5');gr.addColorStop(1,'#ec4899');g.fillStyle=gr;g.fillRect(0,0,W,H);
g.fillStyle='#ffffff';g.beginPath();g.roundRect(18,18,W-36,H-36,28);g.fill();g.fillStyle=gr;g.beginPath();g.roundRect(18,18,W-36,100,[28,28,0,0]);g.fill();
